import os
import json
from typing import Any, Dict, List, Tuple, Optional

import requests


class StructuredDocumentExtractionError(Exception):
    pass


def _flatten_fields(fields: Any, prefix: str = "") -> List[Tuple[str, Any]]:
    items: List[Tuple[str, Any]] = []
    if isinstance(fields, dict):
        for key, value in fields.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            if isinstance(value, dict) and "value" in value:
                items.append((path, value))
            elif isinstance(value, (dict, list)):
                items.extend(_flatten_fields(value, path))
            else:
                items.append((path, value))
    elif isinstance(fields, list):
        for idx, value in enumerate(fields):
            path = f"{prefix}[{idx}]" if prefix else f"[{idx}]"
            if isinstance(value, dict) and "value" in value:
                items.append((path, value))
            elif isinstance(value, (dict, list)):
                items.extend(_flatten_fields(value, path))
            else:
                items.append((path, value))
    return items


def validate_structured_extraction(
    document_url: str,
    required_fields: List[str],
    min_confidence: float = 0.8,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Uses Google Document AI to extract structured data and validates required fields
    plus confidence scores.

    Required environment variable:
        GOOGLE_APPLICATION_CREDENTIALS (for Google client auth) or
        DOCUMENT_AI_API_KEY (if using API key-based access, when supported by your setup)

    This function expects a Document AI processor endpoint.
    """
    api_key = api_key or os.getenv("DOCUMENT_AI_API_KEY")
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    location = os.getenv("DOCUMENT_AI_LOCATION", "us")
    processor_id = os.getenv("DOCUMENT_AI_PROCESSOR_ID")

    if not project_id or not processor_id:
        raise StructuredDocumentExtractionError(
            "Missing GOOGLE_CLOUD_PROJECT or DOCUMENT_AI_PROCESSOR_ID environment variables."
        )

    if not api_key and not os.getenv("GOOGLE_APPLICATION_CREDENTIALS"):
        raise StructuredDocumentExtractionError(
            "Missing authentication. Set GOOGLE_APPLICATION_CREDENTIALS or DOCUMENT_AI_API_KEY."
        )

    # Google Document AI REST API
    url = (
        f"https://{location}-documentai.googleapis.com/v1/"
        f"projects/{project_id}/locations/{location}/processors/{processor_id}:process"
    )

    headers = {"Content-Type": "application/json"}
    if api_key:
        headers["X-Goog-Api-Key"] = api_key

    payload = {
        "inlineDocument": {
            "mimeType": "application/pdf",
            "uri": document_url,
        }
    }

    response = requests.post(url, headers=headers, data=json.dumps(payload), timeout=120)
    if response.status_code >= 400:
        raise StructuredDocumentExtractionError(
            f"Document AI request failed: {response.status_code} {response.text}"
        )

    data = response.json()
    document = data.get("document", {})
    entities = document.get("entities", [])

    extracted: Dict[str, Dict[str, Any]] = {}
    for entity in entities:
        normalized_type = str(entity.get("type", "")).strip()
        if not normalized_type:
            continue
        extracted[normalized_type] = {
            "value": entity.get("normalizedValue", {}).get("text")
            or entity.get("mentionText")
            or entity.get("textAnchor", {}),
            "confidence": float(entity.get("confidence", 0.0) or 0.0),
            "raw": entity,
        }

    missing_fields = [field for field in required_fields if field not in extracted]
    low_confidence_fields = [
        field
        for field in required_fields
        if field in extracted and extracted[field]["confidence"] < min_confidence
    ]

    result = {
        "valid": len(missing_fields) == 0 and len(low_confidence_fields) == 0,
        "required_fields": required_fields,
        "min_confidence": min_confidence,
        "missing_fields": missing_fields,
        "low_confidence_fields": {
            field: extracted[field]["confidence"] for field in low_confidence_fields
        },
        "extracted_fields": extracted,
        "document": document,
        "raw_response": data,
    }

    if not result["valid"]:
        raise StructuredDocumentExtractionError(
            json.dumps(
                {
                    "missing_fields": missing_fields,
                    "low_confidence_fields": {
                        field: extracted[field]["confidence"] for field in low_confidence_fields
                    },
                }
            )
        )

    return result
